${boundaryReview?`<p class="boundary-source-review"><strong>Reference boundary revision:</strong> ${sourceLink(boundaryReview.source,boundaryReview.url)}<br>${escape(boundaryReview.policy.retained_base)}<br>${escape(boundaryReview.policy.outside_component)}<br><strong>New seam coordinates:</strong> ${escape(boundaryReview.vintage)}<br>${escape(boundaryReview.policy.attribution)}<br><strong>License:</strong> ${escape(boundaryReview.license)}<br><strong>Unresolved:</strong> ${escape(boundaryReview.policy.unknown.join('; '))}. This revision does not establish a historical boundary.<br>${escape(boundaryReview.source_offer)}<br>${sourceLink('Retained source and derivative evidence',boundaryReview.derivative_url)}${boundaryReview.original_sources.map(source=>`<br>${sourceLink('Original boundary source',source.url)}`).join('')}</p>`:''}
${chain.some(u=>u.metadata?.kind==='whole_territory')?'<p>A whole-territory group uses the named source territory at this atlas level. Adjacent levels may share a footprint; this is not a separate administrative division.</p>':''}
<p><strong>Boundary:</strong> ${sourceLink(boundary?boundary.source:`${provenance.source_name||'Reference'} · ${provenance.administrative_level||''}`,boundary?.source_url||provenance.source_url)}${provenance.topology_reconciled?'<br><strong>Display boundary:</strong> Reconciled shared coverage; original source geometry may differ.':''}${provenance.location_basis?`<br><strong>Location basis:</strong> ${escape(provenance.location_basis)}`:''}${provenance.scale_review?`<br><strong>Scale review:</strong> ${escape(provenance.scale_review.decision)}`:''}<br><strong>Source date:</strong> ${escape(provenance.reference_year||'Unknown')}<br><strong>Parent match:</strong> ${escape(provenance.parent_match||'Source geography')}<br><strong>License:</strong> ${escape(provenance.license||'See source')}</p>

 const sourceRows=new Map();for(const source of p.sources??[]){const key=assessment.correction?JSON.stringify([source.url,source.role||source.id,source.year,source.license]):source.id;const row=sourceRows.get(key)||{source,count:0};row.count++;sourceRows.set(key,row);}
 const retainedSources=[...sourceRows.values()].map(({source:s,count})=>`<p>${count>1?`${count.toLocaleString()} retained source entries · `:''}<a href="${safe((s.url||'').startsWith('http')?s.url:'https://'+s.url)}" target="_blank" rel="noreferrer">${safe(s.role||s.id)}</a> · ${safe(s.year)} · ${safe(s.license)}</p>`).join('');
 return `<details><summary>${safe(p.owner??'Unassigned reference territory')} · ${p.selected_locations.toLocaleString()} locations in selection · ${safe(p.status)}</summary>${sourcePolicyCoverageHTML(assessment,policySummary)}${assessment.correction&&p.issues?.length?'<p><strong>Earlier review notes:</strong></p>':''}${(p.issues??[]).map(i=>`<p>${safe(i)}</p>`).join('')}<p>${p.open_group_ids.length} groups have open notes.</p>${p.candidate_refinement?`<p>Finer source assessment: ${safe(p.candidate_refinement.status)}</p>`:''}${assessment.correction?`<details><summary>Retained source metadata</summary>${retainedSources}</details>`:retainedSources}<details><summary>Group decisions</summary>${p.open_group_ids.map(id=>{const g=groups.get(id);return g?`<p><strong>${safe(g.name)}</strong> (${safe(g.level)}): ${(g.reasons??[g.basis||'Review notes unavailable in this report.']).map(safe).join('; ')}<br><small>${safe(g.basis)}</small></p>`:`<p>Retained group ${safe(id)}: review notes unavailable in this report.</p>`;}).join('')}</details></details>`;
}).join('');
renderResearch();
dialog.querySelector('#coverage-sources').innerHTML=inventory.sources.filter(s=>s.attributes.includes(attribute)).map(s=>`<p><a href="${safe(s.url)}" target="_blank" rel="noreferrer">${safe(s.name)}</a> · ${safe(s.status)}<br>${safe(s.scope)}<br><small>${safe(s.license)} · ${safe(s.limitation)}</small></p>`).join('');
